package com.turing.app.api.application.entity;
import com.turing.app.api.user.entity.User;import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;
@Entity @Table(name="application_notes") public class ApplicationNote {
 @Id private UUID id;@ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="application_id") private Application application;@ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="admin_id") private User admin;@Column(nullable=false,length=2000) private String content;@Column(nullable=false,length=16) private String visibility;@Column(name="created_at",nullable=false) private Instant createdAt;@Column(name="updated_at",nullable=false) private Instant updatedAt;@Version @Column(nullable=false) private long version;protected ApplicationNote(){}public static ApplicationNote create(Application application,User admin,String content,Instant now){ApplicationNote value=new ApplicationNote();value.id=UUID.randomUUID();value.application=application;value.admin=admin;value.content=content;value.visibility="INTERNAL";value.createdAt=now;value.updatedAt=now;return value;}public UUID getId(){return id;}public User getAdmin(){return admin;}public String getContent(){return content;}public Instant getCreatedAt(){return createdAt;}public long getVersion(){return version;}
}
